WITH cleaned AS (SELECT id, customer_id, store_id, order_date, status, discount, LAST_DAY(order_date) AS order_date_month_end, amount - shipping_fee AS amount_with_shipping, COALESCE(channel, 'N/A') AS channel_filled FROM orders WHERE channel IS NOT DISTINCT FROM 'web') SELECT * FROM (SELECT customer_id, status, amount_with_shipping FROM cleaned) src PIVOT (MAX(amount_with_shipping) FOR status IN ('RETURNED' AS returned, 'SHIPPED' AS shipped));
